def test_empty_page_access_table_yields_empty_action_set_for_every_role(session: Session):
    """Fail-closed (C-2/D-9): with page_access completely empty (un-migrated
    simulation), every non-ADMIN admin resolves an empty action set. ADMIN is
    fixed at EDIT everywhere (D08), so it never fails closed."""
    from app.libs.access.pages import PAGE_IDS

    resolver = _import_resolver()
    for role in (
        AdminRole.RM,
        AdminRole.MOBO,
        AdminRole.PM,
        AdminRole.PC,
        AdminRole.COMPLIANCE,
    ):
        user = make_admin_user(session, role, firebase_uid=f"uid-empty-{role.value}")
        assert resolver.actions_for(user, session) == set()
        assert resolver.levels_for(user, session) == {}
    admin = make_admin_user(session, AdminRole.ADMIN, firebase_uid="uid-empty-ADMIN")
    assert resolver.levels_for(admin, session) == {p: "EDIT" for p in PAGE_IDS}


