def test_edit_is_a_superset_of_view_for_every_page_the_role_holds_at_edit(session: Session):
    """EDIT ⊇ VIEW: for a role holding a page at EDIT (with no override), the
    action set contains at least that page's VIEW bucket."""
    from app.libs.access.pages import PAGE_ACTIONS

    resolver = _import_resolver()
    seed_page_access(session)
    # A fresh PC with no overrides of its own (page_access is role-keyed, so this
    # user automatically inherits PC's seeded levels without world.pc's override).
    pc = make_admin_user(session, AdminRole.PC, firebase_uid="uid-pc-fresh-superset")
    actions = resolver.actions_for(pc, session)
    view_bucket, edit_bucket = PAGE_ACTIONS["pc.model-management"]  # PC is seeded 'edit' here
    assert view_bucket <= actions
    assert edit_bucket <= actions


def test_no_memoisation_a_mutation_between_calls_is_observed(session: Session):
    """NO CACHING (§6 explicit invariant): a level changed between two calls in
    the same session must be observed by the second call."""
    from app.libs.access.repository import AccessRepository

    from app.models.access import AccessLevel

    resolver = _import_resolver()
    rm = make_admin_user(session, AdminRole.RM, firebase_uid="uid-rm-nocache")
    before = resolver.levels_for(rm, session)
    assert "pc.allocation-matrix" not in before  # RM has no seeded row here

    AccessRepository(session).upsert_level(
        page_id="pc.allocation-matrix", role=AdminRole.RM, level=AccessLevel.EDIT
    )
    session.commit()

    after = resolver.levels_for(rm, session)
    assert after["pc.allocation-matrix"] == "EDIT"


def test_no_memoisation_override_revocation_observed_immediately(world, session: Session):
    """Symmetric case: an override that is later expired/removed is reflected
    by the very next call -- no request-scoped or lru_cache-style memoisation."""
    resolver = _import_resolver()
    before = resolver.levels_for(world.pc, session)
    assert before["pc.model-management"] == "VIEW"  # unexpired override in effect

    world.override_view_unexpired.expires_at = datetime.now(timezone.utc) - timedelta(days=1)
    session.add(world.override_view_unexpired)
    session.commit()

    after = resolver.levels_for(world.pc, session)
    assert after["pc.model-management"] == "EDIT"  # role level wins now


